package set;

import java.util.Set;
import java.util.TreeSet;

public class TreeSetDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Set<Integer> tset=new TreeSet<>();
		tset.add(15);
		tset.add(20);
		tset.add(10);
		tset.add(30);
		
		System.out.println(tset);
	}

}
